  4	namespace LoadOrderKeeper.Services
  5	{
  6	    public static class DiffService
  7	    {
  8	        private static readonly ViewTexts.LocalizationService _localization = ViewTexts.LocalizationService.Instance;
  9	
 10	        public static async Task<IReadOnlyList<DiffLineModel>> GetPluginsDiffAsync(AppConfigModel config)
 11	        {
 12	            if (config is null)
 13	            {
 14	                throw new ArgumentNullException(nameof(config));
 15	            }
 16	
 17	            if (!config.IsValid())
 18	            {
 19	                throw new InvalidOperationException("Configuration paths are invalid.");
 20	            }
 21	
 22	            string targetPath = config.GetPluginsFilePath();
 23	            string referencePath = config.GetReferenceFilePath();
 24	
 25	            if (!File.Exists(referencePath))
 26	            {
 27	                throw new FileNotFoundException("Reference file not found.", referencePath);
 28	            }
 29	
 30	            if (!File.Exists(targetPath))
 31	            {
 32	                throw new FileNotFoundException("Plugins file not found.", targetPath);
 33	            }
 34	
 35	            var referenceMods = await FileService.ReadModListAsync(referencePath, isReferenceFile: true).ConfigureAwait(false);
 36	            var currentMods   = await FileService.ReadModListAsync(targetPath).ConfigureAwait(false);
 37	
 38	            var refFileNames = referenceMods.Select(m => m.FileName).ToList();
 39	            var curFileNames = currentMods.Select(m => m.FileName).ToList();
 40	
 41	            var lcs = ComputeLcs(refFileNames, curFileNames, StringComparer.OrdinalIgnoreCase);
 42	
 43	            return ClassifyChanges(referenceMods, currentMods, lcs);
 44	        }
 45	
 46	        /// <summary>
 47	        /// Checks if there are any moved mods that are NOT part of dependent change lists.
 48	        /// These independent moves indicate external reordering that sorting could fix.
 49	        /// </summary>
 50	        public static async Task<bool> HasIndependentMovedModsAsync(AppConfigModel config)
 51	        {
 52	            if (config is null)
 53	            {
 54	                throw new ArgumentNullException(nameof(config));
 55	            }
 56	
 57	            if (!config.IsValid())
 58	            {
 59	                return false;
 60	            }
 61	
 62	            string targetPath = config.GetPluginsFilePath();
 63	            string referencePath = config.GetReferenceFilePath();
 64	
 65	            if (!File.Exists(referencePath) || !File.Exists(targetPath))
 66	            {
 67	                return false;
 68	            }
 69	
 70	            var diffLines = await GetPluginsDiffAsync(config).ConfigureAwait(false);
 71	            
 72	            // Get all mods that are part of dependent change lists
 73	            var dependentMods = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
 74	            foreach (var line in diffLines)
 75	            {
 76	                foreach (var dependent in line.DependentChanges)
 77	                {
 78	                    dependentMods.Add(dependent.FileName);
 79	                }
 80	            }
 81	            
 82	            // Check if there are any moved mods that are NOT in the dependent set
 83	            bool hasIndependentMoves = diffLines.Any(line => 
 84	                line.ChangeType == DiffChangeType.Moved && 
 85	                !dependentMods.Contains(line.FileName));
 86	            
 87	            return hasIndependentMoves;
 88	        }
 89	
 90	        /// <summary>
 91	        /// Computes the Longest Common Subsequence of two string lists using a standard
 92	        /// dynamic-programming approach. Returns a list of paired (refIndex, curIndex) tuples
 93	        /// representing the LCS in order, where refIndex is the position in
 94	        /// <paramref name="reference"/> and curIndex is the position in <paramref name="current"/>.
 95	        /// </summary>
 96	        internal static List<(int refIndex, int curIndex)> ComputeLcs(
 97	            IReadOnlyList<string> reference,
 98	            IReadOnlyList<string> current,
 99	            StringComparer comparer)
100	        {

  1	using System;
